insert into training_plans (id, name, description, focus, phase, source, weeks) values
  ('plan-tri-sprint-first-10wk', 'First Sprint Triathlon', 'Your first triathlon: 750 m swim, 20 km bike, 5 km run. Ten weeks, five days a week, built gently with a lighter week every fourth week. Two swims, two rides and a long run each week, with bricks (ride then run) from the build weeks on. Race day is the last Sunday.', 'multisport', 'specialty', 'prebuilt', $plan$[{"week":1,"phase":"base","deload":false,"days":[{"day":"Mon","type":"rest"},{"day":"Tue","type":"workout","workoutType":"swim","workoutId":"plan-tri-sprint-first-10wk-w1-d1","session":{"name":"CSS test","kind":"test","blurb":"Swim 400 m as fast as you can hold evenly, swim easy for 5 minutes, then 200 m all out. Put both times into Settings to set your CSS.","steps":[{"m":400,"zone":"easy"},{"reps":4,"m":50,"zone":"fast","what":"build","rest":20},{"m":400,"zone":"fast"},{"m":200,"zone":"easy"},{"m":200,"zone":"fast"},{"m":200,"zone":"easy"}]}},{"day":"Wed","type":"workout","workoutType":"cycling","workoutId":"prebuilt-sweetspot-pyramid-40"},{"day":"Thu","type":"rest"},{"day":"Fri","type":"workout","workoutType":"swim","workoutId":"plan-tri-sprint-first-10wk-w1-d4","session":{"name":"Endurance swim","kind":"endurance","blurb":"Hold the same pace on every rep.","steps":[{"m":200,"zone":"easy"},{"reps":2,"m":200,"zone":"steady","rest":20},{"m":200,"zone":"easy"}]}},{"day":"Sat","type":"workout","workoutType":"cycling","workoutId":"prebuilt-endurance-45"},{"day":"Sun","type":"workout","workoutType":"run","workoutId":"plan-tri-sprint-first-10wk-w1-d6","session":{"name":"Long run","kind":"long","blurb":"Keep it easy enough that the last 10 minutes feel as controlled as the first.","steps":[{"mins":25,"zone":"easy"}]}}],"note":"Week one. Start with the CSS test swim and put your times into Settings, so every swim after it has the right paces."},{"week":2,"phase":"base","deload":false,"days":[{"day":"Mon","type":"rest"},{"day":"Tue","type":"workout","workoutType":"swim","workoutId":"plan-tri-sprint-first-10wk-w2-d1","session":{"name":"Technique swim","kind":"easy","blurb":"Pick two drills you know, such as catch-up or fingertip drag. Quality strokes over speed.","steps":[{"m":200,"zone":"easy"},{"reps":5,"m":50,"zone":"drill","what":"drill","rest":15},{"reps":2,"m":100,"zone":"steady","rest":15},{"m":200,"zone":"easy"}]}},{"day":"Wed","type":"workout","workoutType":"cycling","workoutId":"prebuilt-sweetspot-2x15-45"},{"day":"Thu","type":"rest"},{"day":"Fri","type":"workout","workoutType":"swim","workoutId":"plan-tri-sprint-first-10wk-w2-d4","session":{"name":"Endurance swim","kind":"endurance","blurb":"Hold the same pace on every rep.","steps":[{"m":200,"zone":"easy"},{"reps":2,"m":200,"zone":"steady","rest":20},{"m":200,"zone":"easy"}]}},{"day":"Sat","type":"workout","workoutType":"cycling","workoutId":"prebuilt-endurance-cadence-45"},{"day":"Sun","type":"workout","workoutType":"run","workoutId":"plan-tri-sprint-first-10wk-w2-d6","session":{"name":"Long run","kind":"long","blurb":"Keep it easy enough that the last 10 minutes feel as controlled as the first.","steps":[{"mins":25,"zone":"easy"}]}}],"note":"Base week: building endurance in every sport. Most of it should feel comfortable."},{"week":3,"phase":"base","deload":false,"days":[{"day":"Mon","type":"rest"},{"day":"Tue","type":"workout","workoutType":"swim","workoutId":"plan-tri-sprint-first-10wk-w3-d1","session":{"name":"CSS intervals","kind":"quality","blurb":"Your threshold swim. Aim for the same time on every 100.","steps":[{"m":200,"zone":"easy"},{"reps":6,"m":100,"zone":"css","rest":15},{"m":200,"zone":"easy"}]}},{"day":"Wed","type":"workout","workoutType":"cycling","workoutId":"prebuilt-sweetspot-pyramid-40"},{"day":"Thu","type":"rest"},{"day":"Fri","type":"workout","workoutType":"swim","workoutId":"plan-tri-sprint-first-10wk-w3-d4","session":{"name":"Endurance swim","kind":"endurance","blurb":"Hold the same pace on every rep.","steps":[{"m":200,"zone":"easy"},{"reps":3,"m":200,"zone":"steady","rest":20},{"