y swim after it has the right paces."},{"week":2,"phase":"base","deload":false,"days":[{"day":"Mon","type":"rest"},{"day":"Tue","type":"workout","workoutType":"swim","workoutId":"plan-tri-sprint-10wk-w2-d1","session":{"name":"Technique swim","kind":"easy","blurb":"Pick two drills you know, such as catch-up or fingertip drag. Quality strokes over speed.","steps":[{"m":200,"zone":"easy"},{"reps":7,"m":50,"zone":"drill","what":"drill","rest":15},{"reps":4,"m":100,"zone":"steady","rest":15},{"m":200,"zone":"easy"}]}},{"day":"Wed","type":"workout","workoutType":"cycling","workoutId":"prebuilt-sweetspot-pyramid-40"},{"day":"Thu","type":"workout","workoutType":"run","workoutId":"plan-tri-sprint-10wk-w2-d3","session":{"name":"Hill reps","kind":"quality","blurb":"On a steady hill: run up hard and tall, jog back down.","steps":[{"mins":10,"zone":"easy"},{"reps":4,"secs":60,"zone":"interval","rec":{"secs":90,"kind":"jog"}},{"mins":10,"zone":"easy"}]}},{"day":"Fri","type":"workout","workoutType":"swim","workoutId":"plan-tri-sprint-10wk-w2-d4","session":{"name":"Endurance swim","kind":"endurance","blurb":"Hold the same pace on every rep.","steps":[{"m":200,"zone":"easy"},{"reps":4,"m":200,"zone":"steady","rest":20},{"m":200,"zone":"easy"}]}},{"day":"Sat","type":"workout","workoutType":"cycling","workoutId":"prebuilt-endurance-60"},{"day":"Sun","type":"workout","workoutType":"run","workoutId":"plan-tri-sprint-10wk-w2-d6","session":{"name":"Long run","kind":"long","blurb":"Keep it easy enough that the last 10 minutes feel as controlled as the first.","steps":[{"mins":35,"zone":"easy"}]}}],"note":"Base week: building endurance in every sport. Most of it should feel comfortable."},{"week":3,"phase":"base","deload":false,"days":[{"day":"Mon","type":"rest"},{"day":"Tue","type":"workout","workoutType":"swim","workoutId":"plan-tri-sprint-10wk-w3-d1","session":{"name":"CSS intervals","kind":"quality","blurb":"Your threshold swim. Aim for the same time on every 100.","steps":[{"m":200,"zo